// Samuel's email signature banner (1000 x 192 PNG), shown at 500 px wide so it stays sharp on phones.
// Attached inline (cid:kodasig) to every email that goes to a client, so it never depends on a hosted file.
export const SIGNATURE_PNG_BASE64 =
  "";
export const SIGNATURE_ALT = "KODA, Samuel Baradhuwar, Founder. Tel 084 999 7601, hello@heykoda.co.za, heykoda.co.za";
export const SIGNATURE_ATTACHMENT = { filename: "signature.png", content: SIGNATURE_PNG_BASE64, content_type: "image/png", content_id: "kodasig" };
// The image has the contact details in it, so the same details are repeated as real text for mail apps that block images.
export const SIGNATURE_TEXT = "Samuel Baradhuwar, Founder, KODA\nTel 084 999 7601 - hello@heykoda.co.za - heykoda.co.za";
export const signatureHtml = (src = "cid:kodasig") =>
  `<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:500px"><tr><td style="padding:8px 0 0"><a href="https://www.heykoda.co.za" style="text-decoration:none"><img src="${src}" width="500" alt="${SIGNATURE_ALT}" style="display:block;border:0;width:100%;max-width:500px;height:auto;border-radius:12px"></a></td></tr></table>`;
